def find_largest_palindromic_cube(N: int) -> int:
    index = 1
    largest_palindrome = 0
    while True:
        cube = index * index * index
        if cube > N:
            break
        if str(cube) == str(cube)[::-1]:
            largest_palindrome = cube
        index += 1
    return largest_palindrome
